-- Business RPC checks; run after phase1_checks.sql and checkout_checks.sql.
select set_config('session.admin_role', current_user, false);
do $$
declare
 u uuid:='21000000-0000-0000-0000-000000000001'; s uuid; p uuid; c uuid; sup uuid; multi_po uuid; saved_p uuid; expense_id uuid; balance bigint; atomic_sup uuid;
 po uuid; po_n bigint; po_t bigint; item uuid; pay uuid; prior uuid; stock integer; bal bigint;
 cat_product uuid; cat_product2 uuid; cat_id uuid;
 alloc_c uuid; alloc_c2 uuid; sale1 uuid; sale2 uuid; pay_alloc uuid; pay_unalloc uuid;
 lines jsonb; rec jsonb;
begin
 insert into auth.users(id,email) values(u,'rpc-checks@local') on conflict do nothing;
 perform tests.as_user(u); s:=public.create_store('RPC Checks'); perform tests.as_admin();
 insert into public.products(store_id,name,sku,price,cost,stock_quantity) values(s,'RPC Item','RPC-1',100,60,2) returning id into p;
 insert into public.customers(store_id,name,phone,khata_balance) values(s,'RPC Customer','03001112222',500) returning id into c;
 insert into public.suppliers(store_id,name) values(s,'RPC Supplier') returning id into sup;

 perform tests.as_user(u);
 atomic_sup:=public.create_supplier_with_opening_balance(s,'Atomic Vendor','Contact','03001112223','Fabric',250,'rpc-supplier-key-01');
 perform tests.ok(public.create_supplier_with_opening_balance(s,'Atomic Vendor','Contact','03001112223','Fabric',250,'rpc-supplier-key-01')=atomic_sup,'supplier create retry returns same supplier');
 perform tests.ok(tests.try(format('select public.create_supplier_with_opening_balance(%L,%L,%L,%L,%L,251,%L)',s,'Atomic Vendor','Contact','03001112223','Fabric','rpc-supplier-key-01'))='22023','supplier idempotency rejects changed opening balance');
 perform tests.ok(tests.try(format('select public.create_supplier_with_opening_balance(%L,%L,null,null,null,-1,%L)',s,'Invalid Vendor','rpc-supplier-key-02'))='22023','supplier creation rejects negative opening balance');
 perform tests.ok(tests.try(format('select public.create_supplier_with_opening_balance(%L,%L,null,null,null,25,%L)',s,'RPC Supplier','rpc-supplier-key-03'))='23505','supplier duplicate name fails atomically');
 perform tests.as_admin();
 perform tests.ok((select payable_balance=250 from public.suppliers where id=atomic_sup) and (select count(*)=1 from public.supplier_entries where supplier_id=atomic_sup and entry_type='opening_balance'),'supplier and opening ledger row commit atomically exactly once');
 perform tests.ok(not exists(select 1 from public.suppliers where store_id=s and create_idempotency_key='rpc-supplier-key-03'),'failed supplier creation leaves no partial supplier');
 perform tests.as_user(u);
 saved_p:=public.save_product(s,null,'Saved RPC Product','RPC-SAVE-1','RPC Category',120,55,3,2,'Blue','M');
 perform tests.as_admin();
 perform tests.ok((select stock_quantity=3 from public.products where id=saved_p) and (select count(*)=1 from public.stock_movements where product_id=saved_p and movement_type='opening_stock'),'product RPC writes product and opening stock movement atomically');
 perform tests.as_user(u);
 perform tests.ok(tests.try(format('select public.save_product(%L,null,%L,%L,%L,0,0,0,0,null,null)',s,'Bad','RPC-BAD','RPC Category'))='P0001','product RPC rejects invalid price');
 perform tests.ok(public.archive_product(s,saved_p),'product archive RPC succeeds for same store');
 perform tests.as_admin();
 perform tests.ok(not (select is_active from public.products where id=saved_p),'archived product is excluded from active catalog');
 perform tests.as_user(u);
 cat_product:=public.save_product(s,null,'Custom Category Product','RPC-CAT-1','Custom/Other',150,80,4,1,null,null);
 perform tests.as_admin();
 select c.id into cat_id from public.categories c join public.products p on p.category_id=c.id where p.id=cat_product;
 perform tests.ok(cat_id is not null and (select count(*) from public.categories where store_id=s and lower(name)='custom/other')=1,'save_product creates the Custom/Other category row and links the product by ID');
 perform tests.as_user(u);
 update public.categories set name='Boutique' where store_id=s and id=cat_id;
 perform tests.as_admin();
 perform tests.ok((select c.name from public.categories c join public.products p on p.category_id=c.id where p.id=cat_product)='Boutique','editing a category keeps existing products linked by category ID');
 perform tests.as_user(u);
 cat_product2:=public.save_product(s,null,'Boutique Product','RPC-CAT-2','Boutique',175,90,2,1,null,null);
 perform tests.ok(public.save_product(s,cat_product2,'Boutique Product','RPC-CAT-2','Boutique',180,90,2,1,null,null)=cat_product2,'editing a product preserves its existing category');
 perform tests.as_admin();
 perform tests.ok((select c.name from public.categories c join public.products p on p.category_id=c.id where p.id=cat_product2)='Boutique','edited product category persisted');
 perform tests.ok((select count(*) from public.products where store_id=s and category_id=cat_id)=2,'both products are linked to the edited category before deletion');
 perform tests.as_user(u);
 delete from public.categories where store_id=s and id=cat_id;
 perform tests.as_admin();
 perform tests.ok((select count(*) from public.categories where store_id=s and id=cat_id)=0 and (select count(*) from public.products where store_id=s and category_id=cat_id)=0,'database category deletion clears the category link without deleting products');
 perform tests.as_user(u);
 expense_id:=public.save_expense(s,null,'RPC Rent','Rent',1000,current_date,'first');
 perform tests.ok(public.save_expense(s,expense_id,'RPC Rent Updated','Rent',1200,current_date,'updated')=expense_id,'expense RPC updates existing store expense');
 perform tests.as_admin();
 perform tests.ok((select amount=1200 and title='RPC Rent Updated' from public.expenses where id=expense_id),'expense update persisted');
 perform tests.as_user(u);
 perform tests.ok(tests.try(format('select public.adjust_stock(%L,%L,%s,%L)',s,p,-3,'bad'))='23514','stock adjustment cannot underflow');
 perform tests.ok(public.adjust_stock(s,p,3,'restock')=5,'authorized stock adjustment returns resulting stock');
 lines:=jsonb_build_array(jsonb_build_object('product_id',p,'description','RPC Item','quantity',4,'unit_cost',50));
 select * into po,po_n,po_t from public.create_purchase_order(s,sup,current_date,'test',lines,'rpc-po-key-0001');
 select po_id into multi_po from public.create_purchase_order(s,sup,current_date,'multi-line test',jsonb_build_array(jsonb_build_object('product_id',p,'description','RPC Item','quantity',4,'unit_cost',50),jsonb_build_object('product_id',p,'description','RPC Item second line','quantity',2,'unit_cost',25)),'rpc-po-multi-0001');
 perform tests.as_admin();
 perform tests.ok((select total=250 from public.purchase_orders where id=multi_po) and (select count(*)=2 from public.purchase_order_items where purchase_order_id=multi_po),'purchase order creates multiple validated lines and server total');
 perform tests.as_user(u);
 perform tests.ok((select po_id=po and po_number=po_n and total=po_t from public.create_purchase_order(s,sup,current_date,'test',lines,'rpc-po-key-0001')),'PO retry returns same transaction for identical payload');
 perform tests.ok(tests.try(format('select * from public.create_purchase_order(%L,%L,current_date,%L,%L::jsonb,%L)',s,sup,'test',jsonb_build_array(jsonb_build_object('product_id',p,'description','RPC Item','quantity',5,'unit_cost',50)),'rpc-po-key-0001'))='22023','PO idempotency key rejects changed payload');
 perform tests.ok(tests.try(format('select * from public.create_purchase_order(%L,%L,current_date,%L,null,%L)',s,sup,'test','rpc-po-null-0001'))='22023','null PO lines rejected');
 perform tests.ok(tests.try(format('select * from public.create_purchase_order(%L,%L,current_date,%L,%L::jsonb,%L)',s,sup,'test','[{"description":"x","quantity":1,"unit_cost":1,"unexpected":true}]','rpc-po-extra-0001'))='22023','unknown PO line fields rejected');
 perform tests.as_admin();
 select id into item from public.purchase_order_items where purchase_order_id=po;
 perform tests.ok(po_n=101 and po_t=200,'purchase order number and total computed server-side');
 perform tests.as_user(u);
 rec:=jsonb_build_array(jsonb_build_object('item_id',item,'quantity',2));
 perform tests.ok(tests.try(format('select public.receive_purchase_order(%L,%L,null)',s,po))='22023','null receipt list rejected');
 perform tests.ok(public.receive_purchase_order(s,po,rec)=100,'partial receipt value returned');
 perform tests.as_admin();
 perform tests.ok((select stock_quantity from public.products where id=p)=7,'partial receipt adds stock');
 perform tests.ok((select payable_balance from public.suppliers where id=sup)=100,'partial receipt raises supplier payable');
 perform tests.ok((select status from public.purchase_orders where id=po)='pending','partial receipt keeps PO pending');
 perform tests.ok((select count(*) from public.stock_movements where reference_id=po and movement_type='purchase_receipt')=1,'partial receipt appends stock movement');
 perform tests.as_user(u);
 perform tests.ok(public.receive_purchase_order(s,po,jsonb_build_array(jsonb_build_object('item_id',item,'quantity',2)))=100,'remaining receipt completes order');
 perform tests.as_admin();
 perform tests.ok((select status from public.purchase_orders where id=po)='received','complete receipt marks PO received');
 perform tests.ok(tests.try(format('select public.cancel_purchase_order(%L,%L,%L)',s,po,'already received'))='P0002','received PO cannot be cancelled');
 perform tests.ok(tests.try(format('select public.cancel_purchase_order(%L,%L,%L)',s,multi_po,'   '))='22023','blank cancellation reason rejected');
 perform tests.ok(public.cancel_purchase_order(s,multi_po,'test cancellation'),'pending PO cancellation succeeds');
 perform tests.ok((select public.cancel_purchase_order(s, (select po_id from public.create_purchase_order(s,sup,current_date,'cancel test',lines,'rpc-po-key-cancel1')), 'test cancellation')),'pending PO cancellation succeeds');
 perform tests.as_admin();
 perform tests.ok((select status from public.purchase_orders where id=(select po_id from public.create_purchase_order(s,sup,current_date,'cancel test',lines,'rpc-po-key-cancel1')) )='cancelled','cancelled PO status persisted');
 perform tests.as_user(u);
 perform tests.as_user(u);
 pay:=public.record_supplier_payment(s,sup,100,'cash','settlement','rpc-sp-key-0001');
 prior:=public.record_supplier_payment(s,sup,100,'cash','settlement','rpc-sp-key-0001');
 perform tests.ok(pay=prior,'supplier payment retry is idempotent');
 perform tests.ok(tests.try(format('select public.record_supplier_payment(%L,%L,99,%L,%L,%L)',s,sup,'cash','different','rpc-sp-key-0001'))='22023','supplier idempotency key payload mismatch rejected');
 balance:=public.adjust_supplier_balance(s,sup,75,'Opening|balance','rpc-sa-key-0001');
 perform tests.ok(balance=175 and public.adjust_supplier_balance(s,sup,75,'Opening|balance','rpc-sa-key-0001')=175,'supplier adjustment is atomic and idempotent with delimiter characters');
 perform tests.ok(tests.try(format('select public.adjust_supplier_balance(%L,%L,%s,%L,%L)',s,sup,-176,'invalid underflow','rpc-sa-key-0002'))='23514','supplier adjustment cannot underflow payable');
 perform tests.ok(tests.try(format('select public.record_customer_payment(%L,%L,200,%L,%L,%L)',s,c,'cash','payment','rpc-cp-key-0001'))='OK','customer Khata payment accepted');
 perform tests.ok(tests.try(format('select public.record_customer_payment(%L,%L,100,%L,%L,%L)',s,c,'cash','other','rpc-cp-key-0001'))='22023','customer idempotency key payload mismatch rejected');
 perform tests.as_admin();
 insert into public.customers(store_id,name,phone,khata_balance) values(s,'Allocation Customer','03009998888',1000) returning id into alloc_c;
 insert into public.sales(store_id,sale_number,customer_id,customer_name,subtotal,discount,total,cost_total,profit,payment_method,status,idempotency_key)
 values(s,2001,alloc_c,'Allocation Customer',300,0,300,150,150,'credit','pending','alloc-sale-0001')
 returning id into sale1;
 insert into public.sales(store_id,sale_number,customer_id,customer_name,subtotal,discount,total,cost_total,profit,payment_method,status,idempotency_key)
 values(s,2002,alloc_c,'Allocation Customer',150,0,150,70,80,'credit','pending','alloc-sale-0002')
 returning id into sale2;
 perform tests.as_user(u);
 pay_alloc:=public.record_customer_payment_and_allocate(s,alloc_c,300,'cash','part payment','alloc-pay-0001',jsonb_build_array(jsonb_build_object('sale_id',sale1,'amount',200),jsonb_build_object('sale_id',sale2,'amount',50)));
 perform tests.as_admin();
 perform tests.ok((select khata_balance from public.customers where id=alloc_c)=700 and (select amount=300 and unallocated_amount=50 from public.customer_payments where id=pay_alloc),'partial payment reduces customer Khata once and records the unallocated remainder');
 perform tests.ok((select count(*)=2 and coalesce(sum(amount),0)=250 from public.payment_allocations where payment_id=pay_alloc),'payment allocations are stored per sale');
 perform tests.ok((select coalesce(sum(amount),0)=200 from public.payment_allocations where payment_id=pay_alloc and sale_id=sale1),'first sale receives its allocated amount');
 perform tests.ok((select coalesce(sum(amount),0)=50 from public.payment_allocations where payment_id=pay_alloc and sale_id=sale2),'second sale receives its allocated amount');
 perform tests.as_user(u);
 perform tests.ok(public.record_customer_payment_and_allocate(s,alloc_c,300,'cash','part payment','alloc-pay-0001',jsonb_build_array(jsonb_build_object('sale_id',sale1,'amount',200),jsonb_build_object('sale_id',sale2,'amount',50)))=pay_alloc,'payment allocation retry is idempotent');
 perform tests.ok(tests.try(format('select public.record_customer_payment_and_allocate(%L,%L,300,%L,%L,%L,%L::jsonb)',s,alloc_c,'cash','different','alloc-pay-0001',jsonb_build_array(jsonb_build_object('sale_id',sale1,'amount',250))))='22023','payment idempotency key rejects a different allocation payload');
 perform tests.ok(public.allocate_unallocated_payment(s,pay_alloc,jsonb_build_array(jsonb_build_object('sale_id',sale1,'amount',50)),'alloc-rem-0001')=pay_alloc,'remaining unallocated funds can be allocated to a partially paid sale');
 perform tests.as_admin();
 perform tests.ok((select unallocated_amount=0 from public.customer_payments where id=pay_alloc) and (select coalesce(sum(amount),0)=250 from public.payment_allocations where payment_id=pay_alloc and sale_id=sale1),'allocation clears the unallocated balance and updates the sale total');
 perform tests.ok((select status='pending' from public.sales where id=sale1) and (select status='pending' from public.sales where id=sale2),'partially allocated sales remain pending until their total is covered');
 perform tests.ok((select khata_balance from public.customers where id=alloc_c)=700,'allocating existing funds does not change the customer Khata balance again');
 perform tests.as_user(u);
 perform tests.ok(public.allocate_unallocated_payment(s,pay_alloc,jsonb_build_array(jsonb_build_object('sale_id',sale1,'amount',50)),'alloc-rem-0001')=pay_alloc,'allocation retry is idempotent');
 perform tests.ok(tests.try(format('select public.allocate_unallocated_payment(%L,%L,%L::jsonb,%L)',s,pay_alloc,jsonb_build_array(jsonb_build_object('sale_id',sale1,'amount',100)),'alloc-rem-0001'))='22023','allocation idempotency key rejects a different payload');
 perform tests.ok(tests.try(format('select public.allocate_unallocated_payment(%L,%L,%L::jsonb,%L)',s,pay_alloc,jsonb_build_array(jsonb_build_object('sale_id',sale1,'amount',1)),'alloc-over-0001'))='22023','allocation cannot exceed the sale outstanding balance');
 perform tests.as_admin();
 perform tests.ok((select count(*) from public.payment_allocations where payment_id=pay_alloc)=3,'rejected allocations do not create partial rows');
 perform tests.as_user(u);
 pay_unalloc:=public.record_customer_payment_and_allocate(s,alloc_c,100,'cash','unallocated','alloc-pay-0002','[]'::jsonb);
 perform tests.ok(tests.try(format('select public.allocate_unallocated_payment(%L,%L,%L::jsonb,%L)',s,pay_unalloc,jsonb_build_array(jsonb_build_object('sale_id',sale2,'amount',101)),'alloc-over-0002'))='22023','allocation cannot exceed the payment unallocated amount');
 perform tests.as_admin();
 perform tests.ok((select unallocated_amount=100 from public.customer_payments where id=pay_unalloc) and (select count(*) from public.payment_allocations where payment_id=pay_unalloc)=0,'over-allocation attempt leaves the payment and allocations unchanged');
 perform tests.as_user(u);
 perform tests.ok(tests.try(format('select public.create_purchase_order(%L,%L,current_date,%L,%L::jsonb,%L)',s,sup,'x','[]','rpc-po-key-0002'))='22023','empty PO rejected');
 perform tests.as_admin();
 perform tests.ok((select payable_balance from public.suppliers where id=sup)=175,'supplier settlement and adjustment update final payable correctly');
 perform tests.ok((select khata_balance from public.customers where id=c)=300,'Khata payment updates balance atomically');
end $$;
select 'ALL BUSINESS RPC CHECKS PASSED' as result;
